#!/usr/bin/env python3
import re
import sys
from pathlib import Path


def main() -> None:
    guest_source, output_path = map(Path, sys.argv[1:3])
    source = guest_source.read_text(encoding="utf-8")
    declarations = re.findall(
        r"^([A-Za-z_][A-Za-z0-9_ \t*]*?)\s+(hostgl_(gl\w+))\((.*?)\);$",
        source,
        re.M,
    )
    generated = [
        "/* generated by tools/xbox_host_gl.py; do not edit */",
        '#include "host.h"',
        "#include <SDL3/SDL.h>",
        "#include <SDL3/SDL_opengl.h>",
        "#include <SDL3/SDL_opengl_glext.h>",
        "#include <string.h>",
        "",
    ]
    imports = []
    for return_type, host_name, gl_name, parameters in declarations:
        parameters = parameters.strip()
        if gl_name == "glShaderSource":
            generated += [
                (f"void GUEST_ABI {host_name}(GLuint shader, GLsizei count, "
                 "const unsigned long long *strings, const GLint *lengths)"),
                "{",
                "    const GLchar *native[16];",
                "    GLsizei index;",
                "    typedef void (APIENTRY *proc_t)(GLuint, GLsizei, const GLchar *const *, const GLint *);",
                "    static proc_t proc;",
                "",
                "    if (!proc)",
                '        proc = (proc_t)SDL_GL_GetProcAddress("glShaderSource");',
                "    if (count > 16)",
                "        count = 16;",
                "    for (index = 0; index < count; index++)",
                "        native[index] = (const GLchar *)(uintptr_t)strings[index];",
                "    proc(shader, count, native, lengths);",
                "}",
                "",
            ]
            imports.append((host_name, gl_name))
            continue

        parameter_types = [] if parameters in ("", "void") else [item.strip() for item in parameters.split(",")]
        arguments = [f"a{index}" for index in range(len(parameter_types))]
        signature = ", ".join(
            f"{parameter_type} {argument}" for parameter_type, argument in zip(parameter_types, arguments)
        ) or "void"
        call = f"proc({', '.join(arguments)})"
        generated += [
            f"{return_type} GUEST_ABI {host_name}({signature})",
            "{",
            f"    typedef {return_type} (APIENTRY *proc_t)({parameters or 'void'});",
            "    static proc_t proc;",
            "",
            "    if (!proc)",
            f'        proc = (proc_t)SDL_GL_GetProcAddress("{gl_name}");',
            f"    {'return ' if return_type != 'void' else ''}{call};",
            "}",
            "",
        ]
        imports.append((host_name, gl_name))

    generated += [
        "static const struct {",
        "    const char *name;",
        "    void *function;",
        "} xbox_gl_imports[] = {",
        *[f'    {{ "{gl_name}", (void *){host_name} }},' for host_name, gl_name in imports],
        "};",
        "",
        "void *host_gl_resolve(const char *name)",
        "{",
        "    size_t index;",
        "",
        "    for (index = 0; index < sizeof(xbox_gl_imports) / sizeof(xbox_gl_imports[0]); index++)",
        "        if (!strcmp(name, xbox_gl_imports[index].name))",
        "            return xbox_gl_imports[index].function;",
        "    return NULL;",
        "}",
        "",
        "void GUEST_ABI host_gl_get_string(uint32_t name, int index, char *buffer, uint32_t size)",
        "{",
        "    const GLubyte *text = NULL;",
        "",
        "    if (index >= 0)",
        "    {",
        "        typedef const GLubyte *(APIENTRY *proc_t)(GLenum, GLuint);",
        "        static proc_t proc;",
        "",
        "        if (!proc)",
        '            proc = (proc_t)SDL_GL_GetProcAddress("glGetStringi");',
        "        if (proc)",
        "            text = proc(name, index);",
        "    }",
        "    else",
        "    {",
        "        typedef const GLubyte *(APIENTRY *proc_t)(GLenum);",
        "        static proc_t proc;",
        "",
        "        if (!proc)",
        '            proc = (proc_t)SDL_GL_GetProcAddress("glGetString");',
        "        if (proc)",
        "            text = proc(name);",
        "    }",
        "    if (size)",
        "    {",
        "        buffer[0] = 0;",
        "        if (text)",
        "        {",
        "            strncpy(buffer, (const char *)text, size - 1);",
        "            buffer[size - 1] = 0;",
        "        }",
        "    }",
        "}",
        "",
        "int GUEST_ABI host_gl_has_extension(const char *name) { (void)name; return 0; }",
        "uint32_t GUEST_ABI host_gl_read_buffer(uint32_t buffer, uint32_t offset)",
        "{",
        "    (void)buffer;",
        "    (void)offset;",
        "    return 0;",
        "}",
        "uint32_t GUEST_ABI host_gl_read_buffer_word(uint32_t buffer, uint32_t offset)",
        "{",
        "    (void)buffer;",
        "    (void)offset;",
        "    return 0;",
        "}",
        "static GLsync frame_fences[3];",
        "static void *(APIENTRY *map_buffer_range)(GLenum, GLintptr, GLsizeiptr, GLbitfield);",
        "static GLboolean (APIENTRY *unmap_buffer)(GLenum);",
        "static GLsync (APIENTRY *fence_sync)(GLenum, GLbitfield);",
        "static GLenum (APIENTRY *client_wait_sync)(GLsync, GLbitfield, GLuint64);",
        "static void (APIENTRY *delete_sync)(GLsync);",
        "static void (APIENTRY *buffer_sub_data)(GLenum, GLintptr, GLsizeiptr, const void *);",
        "static int stream_initialized, unsynchronized_stream_safe;",
        "",
        "static void stream_initialize(void)",
        "{",
        "    if (stream_initialized)",
        "        return;",
        "    stream_initialized = 1;",
        '    map_buffer_range = (void *)SDL_GL_GetProcAddress("glMapBufferRange");',
        '    unmap_buffer = (void *)SDL_GL_GetProcAddress("glUnmapBuffer");',
        '    fence_sync = (void *)SDL_GL_GetProcAddress("glFenceSync");',
        '    client_wait_sync = (void *)SDL_GL_GetProcAddress("glClientWaitSync");',
        '    delete_sync = (void *)SDL_GL_GetProcAddress("glDeleteSync");',
        '    buffer_sub_data = (void *)SDL_GL_GetProcAddress("glBufferSubData");',
        "    unsynchronized_stream_safe = map_buffer_range && unmap_buffer && fence_sync &&",
        "        client_wait_sync && delete_sync;",
        "}",
        "",
        "void GUEST_ABI host_gl_buffer_write(uint32_t target, uint32_t offset, uint32_t size, const void *data)",
        "{",
        "    void *mapping = NULL;",
        "    stream_initialize();",
        "    if (unsynchronized_stream_safe)",
        "        mapping = map_buffer_range(target, offset, size, GL_MAP_WRITE_BIT | GL_MAP_UNSYNCHRONIZED_BIT);",
        "    if (mapping)",
        "    {",
        "        memcpy(mapping, data, size);",
        "        unmap_buffer(target);",
        "    }",
        "    else if (buffer_sub_data)",
        "        buffer_sub_data(target, offset, size, data);",
        "}",
        "",
        "void GUEST_ABI host_gl_fence_frame(uint32_t slot)",
        "{",
        "    stream_initialize();",
        "    if (!unsynchronized_stream_safe || slot >= 3)",
        "        return;",
        "    if (frame_fences[slot])",
        "        delete_sync(frame_fences[slot]);",
        "    frame_fences[slot] = fence_sync(GL_SYNC_GPU_COMMANDS_COMPLETE, 0);",
        "    if (!frame_fences[slot])",
        "        unsynchronized_stream_safe = 0;",
        "}",
        "",
        "void GUEST_ABI host_gl_wait_frame(uint32_t slot)",
        "{",
        "    GLenum result;",
        "    stream_initialize();",
        "    if (!unsynchronized_stream_safe || slot >= 3 || !frame_fences[slot])",
        "        return;",
        "    result = client_wait_sync(frame_fences[slot], GL_SYNC_FLUSH_COMMANDS_BIT, 1000000000ull);",
        "    delete_sync(frame_fences[slot]);",
        "    frame_fences[slot] = NULL;",
        "    if (result != GL_ALREADY_SIGNALED && result != GL_CONDITION_SATISFIED)",
        "        unsynchronized_stream_safe = 0;",
        "}",
    ]
    output_path.write_text("\n".join(generated) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
